#include <algorithm>
#include <iostream>
#include <vector>
using namespace std;

int n;
vector<long long> h;
vector<int> dq;

// Is there a window of k consecutive buildings whose minimum height is at least k?
bool ok(long long k) {
    int head = 0, tail = 0;
    for (int i = 0; i < n; i++) {
        while (head < tail && dq[head] <= i - k) head++;
        while (head < tail && h[dq[tail - 1]] >= h[i]) tail--;
        dq[tail++] = i;
        if (i >= k - 1 && h[dq[head]] >= k) return true;
    }
    return false;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> n;
    h.resize(n);
    dq.resize(n);
    long long mx = 0;
    for (auto &x : h) {
        cin >> x;
        mx = max(mx, x);
    }
    long long lo = 0, hi = min<long long>(n, mx);
    while (lo < hi) {
        long long mid = (lo + hi + 1) / 2;
        if (ok(mid)) lo = mid;
        else hi = mid - 1;
    }
    cout << lo * lo << '\n';
}

import java.io.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int n;
    static long[] h;
    static int[] dq;

    // Is there a window of k consecutive buildings whose minimum height is at least k?
    static boolean ok(long k) {
        int head = 0, tail = 0;
        for (int i = 0; i < n; i++) {
            while (head < tail && dq[head] <= i - k) head++;
            while (head < tail && h[dq[tail - 1]] >= h[i]) tail--;
            dq[tail++] = i;
            if (i >= k - 1 && h[dq[head]] >= k) return true;
        }
        return false;
    }

    public static void main(String[] args) throws IOException {
        n = (int) nextLong();
        h = new long[n];
        dq = new int[n];
        long mx = 0;
        for (int i = 0; i < n; i++) {
            h[i] = nextLong();
            mx = Math.max(mx, h[i]);
        }
        long lo = 0, hi = Math.min(n, mx);
        while (lo < hi) {
            long mid = (lo + hi + 1) / 2;
            if (ok(mid)) lo = mid;
            else hi = mid - 1;
        }
        System.out.println(lo * lo);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(nextInt())
	h := make([]int64, n)
	var mx int64
	for i := range h {
		h[i] = nextInt()
		mx = max(mx, h[i])
	}
	dq := make([]int, n)
	// Is there a window of k consecutive buildings whose minimum height is at least k?
	ok := func(k int64) bool {
		head, tail := 0, 0
		for i := 0; i < n; i++ {
			for head < tail && int64(dq[head]) <= int64(i)-k {
				head++
			}
			for head < tail && h[dq[tail-1]] >= h[i] {
				tail--
			}
			dq[tail] = i
			tail++
			if int64(i) >= k-1 && h[dq[head]] >= k {
				return true
			}
		}
		return false
	}
	lo, hi := int64(0), min(int64(n), mx)
	for lo < hi {
		mid := (lo + hi + 1) / 2
		if ok(mid) {
			lo = mid
		} else {
			hi = mid - 1
		}
	}
	fmt.Println(lo * lo)
}
